UPDATE `exercises`
SET `name` = (SELECT r.`name` FROM `renamed` AS r WHERE r.`id` = `exercises`.`id`), `updated_at` = '2026-10-04T00:00:00.000Z'
WHERE `is_custom` = 0 AND `id` IN (SELECT `id` FROM `renamed`)
AND NOT EXISTS (SELECT 1 FROM `renamed` AS r JOIN `exercises` AS other ON lower(other.`name`) = lower(r.`name`)
  WHERE r.`id` = `exercises`.`id` AND other.`id` <> `exercises`.`id` AND other.`deleted_at` IS NULL);
--> statement-breakpoint
-- 3. Muscles: 18 dataset exercises that are a built-in's movement on other equipment take its
--    primary muscle (dumbbell squats: quads, as for the barbell squat); the old one becomes a secondary one.
WITH `aligned`(`id`, `primary`, `secondary`) AS (VALUES
('deadlift-cable','lower_back','["quads","hamstrings","glutes"]'),
('deadlift-dumbbell','lower_back','["hamstrings","glutes"]'),
('deadlift-machine','lower_back','["quads","hamstrings","glutes"]'),
('lunge-barbell','quads','["hamstrings","glutes","calves"]'),
('squat-band','quads','["hamstrings","glutes","calves"]'),
('squat-dumbbell','quads','["hamstrings","glutes","calves"]'),
('squat-machine','quads','["hamstrings","glutes","calves"]'),
('walking-lunge','quads','["hamstrings","glutes","calves"]'),
('front-squat-kettlebell','quads','["hamstrings","glutes","calves"]'),
('hack-squat-barbell','quads','["hamstrings","glutes","calves"]'),
('reverse-curl-cable','forearms','["biceps"]'),
('step-up-band','quads','["hamstrings","glutes","calves"]'),
('step-up-barbell','quads','["hamstrings","glutes","calves"]'),
('front-squat-clean-grip-machine','quads','["abs","hamstrings","glutes","calves"]'),
('seated-good-morning-machine','lower_back','["hamstrings","glutes"]'),
('standing-reverse-curl-dumbbell','forearms','["biceps"]'),
('forward-lunge','quads','["hamstrings","glutes","calves"]'),
('stiff-leg-deadlift-band','hamstrings','["lower_back","glutes"]')
)
UPDATE `exercises` SET
  `primary_muscle` = (SELECT a.`primary` FROM `aligned` AS a WHERE a.`id` = `exercises`.`id`),
  `secondary_muscles` = (SELECT a.`secondary` FROM `aligned` AS a WHERE a.`id` = `exercises`.`id`),
  `updated_at` = '2026-10-04T00:00:00.000Z'
WHERE `is_custom` = 0 AND `id` IN (SELECT `id` FROM `aligned`);
